-- Consent templates seed (OneCare set Rev. 06/2026). Idempotent by Code; updates body/schema on re-run.
IF NOT EXISTS (SELECT 1 FROM dbo.ConsentTemplates WHERE Code = 'OC-PHI-001')
  INSERT INTO dbo.ConsentTemplates (Code, Title, Revision, Citation, Summary, BodyHtml, FieldSchema, SignerRoles, RequiredAtIntake, SortOrder, IsActive) VALUES (N'OC-PHI-001', N'Authorization for Use and Disclosure of Protected Health Information', N'06/2026', N'HIPAA 45 CFR 164.508 - 45 CFR Parts 160 and 164 - 42 CFR Part 2 - NC G.S. 122C-52 through 122C-56 - NC G.S. 130A-143', N'Lets OneCare share your crisis and treatment records with the people and providers you name, for the reasons you choose, until the date you choose. You can refuse or revoke it at any time.', N'<section class="cf-sec"><h3>Section 1 - Client Information</h3><div class="cf-client" data-slot="client"></div></section><section class="cf-sec"><h3>Section 2 - Persons / Organizations Authorized to Disclose</h3><p>I authorize the following person(s) or organization(s) to disclose my protected health information:</p><div class="cf-fields" data-slot="fields-disclose"></div></section><section class="cf-sec"><h3>Section 3 - Persons / Organizations Authorized to Receive</h3><p>I authorize that my protected health information be disclosed to:</p><div class="cf-fields" data-slot="fields-receive"></div></section><section class="cf-sec"><h3>Section 4 - Information to be Disclosed</h3><p>I authorize the disclosure of the following types of protected health information (check all that apply):</p><div class="cf-fields" data-slot="fields-info"></div></section><section class="cf-sec"><h3>Section 5 - Purpose of Disclosure</h3><p>The information described above is being disclosed for the following purpose(s):</p><div class="cf-fields" data-slot="fields-purpose"></div></section><section class="cf-sec"><h3>Section 6 - Authorization Period</h3><p>This authorization shall remain in effect:</p><div class="cf-fields" data-slot="fields-period"></div><p>If no date or event is specified, this authorization will expire one (1) year from the date of signature.</p></section><section class="cf-sec"><h3>Section 7 - Client Rights</h3><p>I understand that:</p><ol><li>I have the right to revoke this authorization at any time by submitting a written request to OneCare Behavioral Health Services, except to the extent that action has already been taken in reliance on this authorization.</li><li>I may refuse to sign this authorization and that my refusal will not affect my ability to obtain treatment, payment, enrollment in a health plan, or eligibility for benefits, unless the authorization is a condition of research-related treatment or required for payment of a specific claim.</li><li>Information disclosed pursuant to this authorization may be re-disclosed by the recipient and may no longer be protected by federal or state privacy regulations.</li><li>If this authorization covers substance use disorder records protected by 42 CFR Part 2, the recipient is prohibited from further disclosure without my written consent or as otherwise permitted by federal regulation.</li><li>I am entitled to receive a copy of this authorization after I have signed it.</li><li>Psychotherapy notes (as defined by HIPAA) are excluded from this authorization unless specifically indicated above.</li></ol></section><p class="cf-fine">This form must be completed in full before any protected health information is disclosed. A copy of the signed authorization must be provided to the client and placed in the client''s secure file. Substance use disorder records require separate 42 CFR Part 2 compliant procedures.</p>', N'[{"key": "disclose", "type": "orgs", "label": "Authorized to disclose", "rows": 2, "default": [{"name": "OneCare Behavioral Health Services - Mobile Crisis Management", "contact": ""}]}, {"key": "receive", "type": "orgs", "label": "Authorized to receive", "rows": 2, "default": []}, {"key": "info", "type": "checks", "label": "Information to be disclosed", "required": true, "options": ["Complete health/medical records", "Mental health assessment / evaluation records", "Crisis intervention and safety plan records", "Psychiatric records (excluding psychotherapy notes)", "Psychological / neuropsychological testing", "Substance use disorder treatment records (42 CFR Part 2)", "Medication records and prescriptions", "Discharge summary / treatment plan", "HIV/AIDS-related information", "Lab results and diagnostic imaging", "Billing and insurance records"], "other": true, "default": ["Mental health assessment / evaluation records", "Crisis intervention and safety plan records", "Discharge summary / treatment plan"]}, {"key": "purpose", "type": "checks", "label": "Purpose of disclosure", "required": true, "options": ["Continuity of care / treatment coordination", "Referral to another provider or facility", "Insurance / billing / payment", "Legal proceedings", "Disability determination", "Personal / at client''s request"], "other": true, "default": ["Continuity of care / treatment coordination", "Referral to another provider or facility"]}, {"key": "period", "type": "radio", "label": "Authorization period", "required": true, "options": [{"v": "date", "t": "Until the following date", "input": "date"}, {"v": "event", "t": "Until the following event", "input": "text"}, {"v": "year", "t": "For one (1) year from the date of signature"}, {"v": "discharge", "t": "Upon discharge from services"}], "default": "year"}]', N'Client', 1, 1, 1);
ELSE
  UPDATE dbo.ConsentTemplates SET Title = N'Authorization for Use and Disclosure of Protected Health Information', Revision = N'06/2026', Citation = N'HIPAA 45 CFR 164.508 - 45 CFR Parts 160 and 164 - 42 CFR Part 2 - NC G.S. 122C-52 through 122C-56 - NC G.S. 130A-143', Summary = N'Lets OneCare share your crisis and treatment records with the people and providers you name, for the reasons you choose, until the date you choose. You can refuse or revoke it at any time.', BodyHtml = N'<section class="cf-sec"><h3>Section 1 - Client Information</h3><div class="cf-client" data-slot="client"></div></section><section class="cf-sec"><h3>Section 2 - Persons / Organizations Authorized to Disclose</h3><p>I authorize the following person(s) or organization(s) to disclose my protected health information:</p><div class="cf-fields" data-slot="fields-disclose"></div></section><section class="cf-sec"><h3>Section 3 - Persons / Organizations Authorized to Receive</h3><p>I authorize that my protected health information be disclosed to:</p><div class="cf-fields" data-slot="fields-receive"></div></section><section class="cf-sec"><h3>Section 4 - Information to be Disclosed</h3><p>I authorize the disclosure of the following types of protected health information (check all that apply):</p><div class="cf-fields" data-slot="fields-info"></div></section><section class="cf-sec"><h3>Section 5 - Purpose of Disclosure</h3><p>The information described above is being disclosed for the following purpose(s):</p><div class="cf-fields" data-slot="fields-purpose"></div></section><section class="cf-sec"><h3>Section 6 - Authorization Period</h3><p>This authorization shall remain in effect:</p><div class="cf-fields" data-slot="fields-period"></div><p>If no date or event is specified, this authorization will expire one (1) year from the date of signature.</p></section><section class="cf-sec"><h3>Section 7 - Client Rights</h3><p>I understand that:</p><ol><li>I have the right to revoke this authorization at any time by submitting a written request to OneCare Behavioral Health Services, except to the extent that action has already been taken in reliance on this authorization.</li><li>I may refuse to sign this authorization and that my refusal will not affect my ability to obtain treatment, payment, enrollment in a health plan, or eligibility for benefits, unless the authorization is a condition of research-related treatment or required for payment of a specific claim.</li><li>Information disclosed pursuant to this authorization may be re-disclosed by the recipient and may no longer be protected by federal or state privacy regulations.</li><li>If this authorization covers substance use disorder records protected by 42 CFR Part 2, the recipient is prohibited from further disclosure without my written consent or as otherwise permitted by federal regulation.</li><li>I am entitled to receive a copy of this authorization after I have signed it.</li><li>Psychotherapy notes (as defined by HIPAA) are excluded from this authorization unless specifically indicated above.</li></ol></section><p class="cf-fine">This form must be completed in full before any protected health information is disclosed. A copy of the signed authorization must be provided to the client and placed in the client''s secure file. Substance use disorder records require separate 42 CFR Part 2 compliant procedures.</p>', FieldSchema = N'[{"key": "disclose", "type": "orgs", "label": "Authorized to disclose", "rows": 2, "default": [{"name": "OneCare Behavioral Health Services - Mobile Crisis Management", "contact": ""}]}, {"key": "receive", "type": "orgs", "label": "Authorized to receive", "rows": 2, "default": []}, {"key": "info", "type": "checks", "label": "Information to be disclosed", "required": true, "options": ["Complete health/medical records", "Mental health assessment / evaluation records", "Crisis intervention and safety plan records", "Psychiatric records (excluding psychotherapy notes)", "Psychological / neuropsychological testing", "Substance use disorder treatment records (42 CFR Part 2)", "Medication records and prescriptions", "Discharge summary / treatment plan", "HIV/AIDS-related information", "Lab results and diagnostic imaging", "Billing and insurance records"], "other": true, "default": ["Mental health assessment / evaluation records", "Crisis intervention and safety plan records", "Discharge summary / treatment plan"]}, {"key": "purpose", "type": "checks", "label": "Purpose of disclosure", "required": true, "options": ["Continuity of care / treatment coordination", "Referral to another provider or facility", "Insurance / billing / payment", "Legal proceedings", "Disability determination", "Personal / at client''s request"], "other": true, "default": ["Continuity of care / treatment coordination", "Referral to another provider or facility"]}, {"key": "period", "type": "radio", "label": "Authorization period", "required": true, "options": [{"v": "date", "t": "Until the following date", "input": "date"}, {"v": "event", "t": "Until the following event", "input": "text"}, {"v": "year", "t": "For one (1) year from the date of signature"}, {"v": "discharge", "t": "Upon discharge from services"}], "default": "year"}]', SignerRoles = N'Client', RequiredAtIntake = 1, SortOrder = 1 WHERE Code = 'OC-PHI-001';
IF NOT EXISTS (SELECT 1 FROM dbo.ConsentTemplates WHERE Code = 'OC-CST-002')
  INSERT INTO dbo.ConsentTemplates (Code, Title, Revision, Citation, Summary, BodyHtml, FieldSchema, SignerRoles, RequiredAtIntake, SortOrder, IsActive) VALUES (N'OC-CST-002', N'Informed Consent for Mobile Crisis Management Services', N'06/2026', N'NC Medicaid Clinical Coverage Policy 8A, Attachment D (MCM) - NC G.S. 122C - HIPAA 45 CFR 164.508 - 42 CFR Part 2', N'Explains the mobile crisis services OneCare will provide, how AI-assisted tools are used under clinician review, your rights, and the limits of confidentiality. Signing means you agree to receive the services.', N'<section class="cf-sec"><h3>Section 1 - Client Information</h3><div class="cf-client" data-slot="client"></div><div class="cf-fields" data-slot="fields-emergency"></div></section><section class="cf-sec"><h3>Section 2 - Description of Services</h3><p>OneCare Behavioral Health Services provides Mobile Crisis Management (MCM) services in accordance with NC Medicaid Clinical Coverage Policy 8A (Enhanced Mental Health and Substance Abuse Services, Attachment D). These services include, but are not limited to:</p><ol><li>Crisis triage and screening via telephone, telehealth, or in-person contact to evaluate the nature and severity of the presenting crisis</li><li>Face-to-face crisis assessment by a Qualified Professional (QP) or Licensed Clinician within the required timeframe</li><li>Crisis intervention and de-escalation using evidence-based, trauma-informed practices</li><li>Safety planning including identification of warning signs, coping strategies, and support contacts</li><li>Crisis plan development in collaboration with the client, family members, and treatment team</li><li>Service linkage and referral to appropriate levels of care, community resources, and ongoing treatment providers</li><li>Follow-up contact within the timeframe required by NC Medicaid policy to ensure continuity of care</li><li>Coordination with emergency services including 911, law enforcement, and emergency departments when clinically indicated</li></ol></section><section class="cf-sec"><h3>Section 3 - AI-Assisted Clinical Technology</h3><p>OneCare BHS utilizes AI-assisted technology (GeniusOne AI) to support clinical operations. By signing this consent, you acknowledge and agree that:</p><ol><li>AI technology may assist with initial call triage and routing to the appropriate crisis response team</li><li>AI-powered clinical documentation tools may be used to assist workers with note-taking and assessment completion</li><li>All clinical decisions are made by licensed and/or qualified human professionals; AI does not make treatment, diagnostic, or disposition decisions</li><li>AI-generated content is reviewed and approved by a licensed clinician before it becomes part of your clinical record</li><li>All AI systems comply with HIPAA security requirements and data is encrypted in transit and at rest</li></ol></section><section class="cf-sec"><h3>Section 4 - Client Rights</h3><p>As a client of OneCare Behavioral Health Services, you have the right to:</p><ol><li>Receive services in a safe, respectful, and culturally sensitive manner</li><li>Be informed of your diagnosis, treatment options, and prognosis in language you understand</li><li>Refuse or withdraw from any service at any time without penalty, except as required by law (e.g., involuntary commitment proceedings under NC G.S. 122C-261 et seq.)</li><li>Confidentiality of your health information in accordance with HIPAA, 42 CFR Part 2, and NC G.S. 122C-52 through 122C-56</li><li>Request restriction of certain disclosures of your health information</li><li>Access and obtain copies of your health records</li><li>File a grievance or complaint with OneCare BHS, your Prepaid Health Plan, or the NC DHHS Division of Health Service Regulation without fear of retaliation</li><li>Participate in the development of your treatment / crisis plan</li><li>Be free from abuse, neglect, exploitation, and discrimination</li><li>Opt out of AI-assisted services and receive equivalent human-only service delivery</li></ol></section><section class="cf-sec"><h3>Section 5 - Limits of Confidentiality</h3><p>I understand that my provider is required by law to disclose information without my authorization in the following situations:</p><ol><li>Imminent danger to myself or others (duty to warn / protect)</li><li>Suspected abuse or neglect of a child, disabled adult, or elder (NC G.S. 7B-301, 108A-102)</li><li>Court order or lawful subpoena</li><li>Involuntary commitment proceedings (NC G.S. 122C-261 et seq.)</li><li>Medical emergencies when the client is unable to provide consent</li></ol></section><section class="cf-sec"><h3>Section 6 - Acknowledgment</h3><p>By signing below, I acknowledge that I have read (or have had read to me) and understand the information provided in this consent form. I voluntarily consent to receive Mobile Crisis Management Services from OneCare Behavioral Health Services. I have been given the opportunity to ask questions, and my questions have been answered to my satisfaction.</p><p class="cf-fine">Verbal Consent - If written consent cannot be obtained due to the crisis situation, the crisis worker must document verbal consent on Form OC-VCD-003 including date and time, name of the person giving consent, relationship to client, summary of information conveyed, and worker signature. Written consent must be obtained at the earliest opportunity.</p></section>', N'[{"key": "emergency", "type": "text", "label": "Emergency contact / phone", "required": false, "prefill": "nextOfKin"}]', N'Client,Worker', 1, 2, 1);
ELSE
  UPDATE dbo.ConsentTemplates SET Title = N'Informed Consent for Mobile Crisis Management Services', Revision = N'06/2026', Citation = N'NC Medicaid Clinical Coverage Policy 8A, Attachment D (MCM) - NC G.S. 122C - HIPAA 45 CFR 164.508 - 42 CFR Part 2', Summary = N'Explains the mobile crisis services OneCare will provide, how AI-assisted tools are used under clinician review, your rights, and the limits of confidentiality. Signing means you agree to receive the services.', BodyHtml = N'<section class="cf-sec"><h3>Section 1 - Client Information</h3><div class="cf-client" data-slot="client"></div><div class="cf-fields" data-slot="fields-emergency"></div></section><section class="cf-sec"><h3>Section 2 - Description of Services</h3><p>OneCare Behavioral Health Services provides Mobile Crisis Management (MCM) services in accordance with NC Medicaid Clinical Coverage Policy 8A (Enhanced Mental Health and Substance Abuse Services, Attachment D). These services include, but are not limited to:</p><ol><li>Crisis triage and screening via telephone, telehealth, or in-person contact to evaluate the nature and severity of the presenting crisis</li><li>Face-to-face crisis assessment by a Qualified Professional (QP) or Licensed Clinician within the required timeframe</li><li>Crisis intervention and de-escalation using evidence-based, trauma-informed practices</li><li>Safety planning including identification of warning signs, coping strategies, and support contacts</li><li>Crisis plan development in collaboration with the client, family members, and treatment team</li><li>Service linkage and referral to appropriate levels of care, community resources, and ongoing treatment providers</li><li>Follow-up contact within the timeframe required by NC Medicaid policy to ensure continuity of care</li><li>Coordination with emergency services including 911, law enforcement, and emergency departments when clinically indicated</li></ol></section><section class="cf-sec"><h3>Section 3 - AI-Assisted Clinical Technology</h3><p>OneCare BHS utilizes AI-assisted technology (GeniusOne AI) to support clinical operations. By signing this consent, you acknowledge and agree that:</p><ol><li>AI technology may assist with initial call triage and routing to the appropriate crisis response team</li><li>AI-powered clinical documentation tools may be used to assist workers with note-taking and assessment completion</li><li>All clinical decisions are made by licensed and/or qualified human professionals; AI does not make treatment, diagnostic, or disposition decisions</li><li>AI-generated content is reviewed and approved by a licensed clinician before it becomes part of your clinical record</li><li>All AI systems comply with HIPAA security requirements and data is encrypted in transit and at rest</li></ol></section><section class="cf-sec"><h3>Section 4 - Client Rights</h3><p>As a client of OneCare Behavioral Health Services, you have the right to:</p><ol><li>Receive services in a safe, respectful, and culturally sensitive manner</li><li>Be informed of your diagnosis, treatment options, and prognosis in language you understand</li><li>Refuse or withdraw from any service at any time without penalty, except as required by law (e.g., involuntary commitment proceedings under NC G.S. 122C-261 et seq.)</li><li>Confidentiality of your health information in accordance with HIPAA, 42 CFR Part 2, and NC G.S. 122C-52 through 122C-56</li><li>Request restriction of certain disclosures of your health information</li><li>Access and obtain copies of your health records</li><li>File a grievance or complaint with OneCare BHS, your Prepaid Health Plan, or the NC DHHS Division of Health Service Regulation without fear of retaliation</li><li>Participate in the development of your treatment / crisis plan</li><li>Be free from abuse, neglect, exploitation, and discrimination</li><li>Opt out of AI-assisted services and receive equivalent human-only service delivery</li></ol></section><section class="cf-sec"><h3>Section 5 - Limits of Confidentiality</h3><p>I understand that my provider is required by law to disclose information without my authorization in the following situations:</p><ol><li>Imminent danger to myself or others (duty to warn / protect)</li><li>Suspected abuse or neglect of a child, disabled adult, or elder (NC G.S. 7B-301, 108A-102)</li><li>Court order or lawful subpoena</li><li>Involuntary commitment proceedings (NC G.S. 122C-261 et seq.)</li><li>Medical emergencies when the client is unable to provide consent</li></ol></section><section class="cf-sec"><h3>Section 6 - Acknowledgment</h3><p>By signing below, I acknowledge that I have read (or have had read to me) and understand the information provided in this consent form. I voluntarily consent to receive Mobile Crisis Management Services from OneCare Behavioral Health Services. I have been given the opportunity to ask questions, and my questions have been answered to my satisfaction.</p><p class="cf-fine">Verbal Consent - If written consent cannot be obtained due to the crisis situation, the crisis worker must document verbal consent on Form OC-VCD-003 including date and time, name of the person giving consent, relationship to client, summary of information conveyed, and worker signature. Written consent must be obtained at the earliest opportunity.</p></section>', FieldSchema = N'[{"key": "emergency", "type": "text", "label": "Emergency contact / phone", "required": false, "prefill": "nextOfKin"}]', SignerRoles = N'Client,Worker', RequiredAtIntake = 1, SortOrder = 2 WHERE Code = 'OC-CST-002';
IF NOT EXISTS (SELECT 1 FROM dbo.ConsentTemplates WHERE Code = 'OC-VCD-003')
  INSERT INTO dbo.ConsentTemplates (Code, Title, Revision, Citation, Summary, BodyHtml, FieldSchema, SignerRoles, RequiredAtIntake, SortOrder, IsActive) VALUES (N'OC-VCD-003', N'Verbal Consent Documentation Form', N'06/2026', N'NC Medicaid Clinical Coverage Policy 8A, Attachment D (MCM) - NC Medicaid Policy 1H (Telehealth) - NC G.S. 122C-52 through 122C-56', N'Worker record that the client (or representative) gave verbal consent when written consent could not be obtained. Written consent is still required at the earliest opportunity (72-hour task).', N'<section class="cf-sec"><h3>Section 1 - Client Information</h3><div class="cf-client" data-slot="client"></div></section><section class="cf-sec"><h3>Section 2 - Reason Written Consent Was Not Obtained</h3><div class="cf-fields" data-slot="fields-reason"></div></section><section class="cf-sec"><h3>Section 3 - Identity Verification (Two-Point ID)</h3><p>Per NC Medicaid policy, the provider must verify the beneficiary''s identity using two points of identification before initiating telephonic or audio-only services.</p><div class="cf-fields" data-slot="fields-identity"></div></section><section class="cf-sec"><h3>Section 4 - Consent Statement Read to Client</h3><blockquote>"My name is [Worker Name], and I am a [credential/title] with OneCare Behavioral Health Services. I am calling regarding crisis services. With your permission, I would like to proceed with a crisis assessment and provide you with support. You have the right to refuse services at any time. The information you share will be kept confidential in accordance with state and federal law, except in situations involving imminent danger to yourself or others, suspected abuse or neglect, or court order. Do you understand and agree to proceed?"</blockquote></section><section class="cf-sec"><h3>Section 5 - Consent Details</h3><div class="cf-fields" data-slot="fields-details"></div></section><section class="cf-sec"><h3>Section 7 - Worker Attestation</h3><p>I attest that verbal consent was obtained as documented above. I read (or caused to be read) the consent statement to the client or their authorized representative, and the person indicated their understanding and agreement to proceed. I will obtain written consent at the earliest opportunity.</p></section>', N'[{"key": "reason", "type": "radio", "label": "Reason", "required": true, "options": [{"v": "crisis", "t": "Active crisis situation - client unable to sign written documents"}, {"v": "audio", "t": "Telephonic / audio-only service delivery"}, {"v": "video", "t": "Telehealth video service delivery"}, {"v": "physical", "t": "Client physically unable to sign (medical condition, restraint, transport)"}, {"v": "minor", "t": "Minor - parent/guardian consent obtained by phone"}, {"v": "other", "t": "Other", "input": "text"}]}, {"key": "identity", "type": "kv", "label": "Two-point identification", "required": true, "items": [{"k": "id1", "t": "ID point 1 (e.g., full legal name)"}, {"k": "id2", "t": "ID point 2 (e.g., date of birth, SSN last 4, address)"}]}, {"key": "details", "type": "kv", "label": "Consent details", "required": true, "items": [{"k": "person", "t": "Person giving verbal consent (full name)"}, {"k": "relationship", "t": "Relationship to client"}, {"k": "method", "t": "Method (Phone / Video / In-person)", "options": ["Phone", "Video", "In-person"]}, {"k": "services", "t": "Services consented to", "checks": ["Mobile Crisis Management Services", "Release of PHI for care coordination", "AI-assisted triage and documentation", "Telehealth / telephonic service delivery"]}, {"k": "support", "t": "Contact with family member / support person (name)", "optional": true}, {"k": "referral", "t": "Referral to", "optional": true}]}]', N'Worker', 0, 3, 1);
ELSE
  UPDATE dbo.ConsentTemplates SET Title = N'Verbal Consent Documentation Form', Revision = N'06/2026', Citation = N'NC Medicaid Clinical Coverage Policy 8A, Attachment D (MCM) - NC Medicaid Policy 1H (Telehealth) - NC G.S. 122C-52 through 122C-56', Summary = N'Worker record that the client (or representative) gave verbal consent when written consent could not be obtained. Written consent is still required at the earliest opportunity (72-hour task).', BodyHtml = N'<section class="cf-sec"><h3>Section 1 - Client Information</h3><div class="cf-client" data-slot="client"></div></section><section class="cf-sec"><h3>Section 2 - Reason Written Consent Was Not Obtained</h3><div class="cf-fields" data-slot="fields-reason"></div></section><section class="cf-sec"><h3>Section 3 - Identity Verification (Two-Point ID)</h3><p>Per NC Medicaid policy, the provider must verify the beneficiary''s identity using two points of identification before initiating telephonic or audio-only services.</p><div class="cf-fields" data-slot="fields-identity"></div></section><section class="cf-sec"><h3>Section 4 - Consent Statement Read to Client</h3><blockquote>"My name is [Worker Name], and I am a [credential/title] with OneCare Behavioral Health Services. I am calling regarding crisis services. With your permission, I would like to proceed with a crisis assessment and provide you with support. You have the right to refuse services at any time. The information you share will be kept confidential in accordance with state and federal law, except in situations involving imminent danger to yourself or others, suspected abuse or neglect, or court order. Do you understand and agree to proceed?"</blockquote></section><section class="cf-sec"><h3>Section 5 - Consent Details</h3><div class="cf-fields" data-slot="fields-details"></div></section><section class="cf-sec"><h3>Section 7 - Worker Attestation</h3><p>I attest that verbal consent was obtained as documented above. I read (or caused to be read) the consent statement to the client or their authorized representative, and the person indicated their understanding and agreement to proceed. I will obtain written consent at the earliest opportunity.</p></section>', FieldSchema = N'[{"key": "reason", "type": "radio", "label": "Reason", "required": true, "options": [{"v": "crisis", "t": "Active crisis situation - client unable to sign written documents"}, {"v": "audio", "t": "Telephonic / audio-only service delivery"}, {"v": "video", "t": "Telehealth video service delivery"}, {"v": "physical", "t": "Client physically unable to sign (medical condition, restraint, transport)"}, {"v": "minor", "t": "Minor - parent/guardian consent obtained by phone"}, {"v": "other", "t": "Other", "input": "text"}]}, {"key": "identity", "type": "kv", "label": "Two-point identification", "required": true, "items": [{"k": "id1", "t": "ID point 1 (e.g., full legal name)"}, {"k": "id2", "t": "ID point 2 (e.g., date of birth, SSN last 4, address)"}]}, {"key": "details", "type": "kv", "label": "Consent details", "required": true, "items": [{"k": "person", "t": "Person giving verbal consent (full name)"}, {"k": "relationship", "t": "Relationship to client"}, {"k": "method", "t": "Method (Phone / Video / In-person)", "options": ["Phone", "Video", "In-person"]}, {"k": "services", "t": "Services consented to", "checks": ["Mobile Crisis Management Services", "Release of PHI for care coordination", "AI-assisted triage and documentation", "Telehealth / telephonic service delivery"]}, {"k": "support", "t": "Contact with family member / support person (name)", "optional": true}, {"k": "referral", "t": "Referral to", "optional": true}]}]', SignerRoles = N'Worker', RequiredAtIntake = 0, SortOrder = 3 WHERE Code = 'OC-VCD-003';
IF NOT EXISTS (SELECT 1 FROM dbo.ConsentTemplates WHERE Code = 'OC-NPP-004')
  INSERT INTO dbo.ConsentTemplates (Code, Title, Revision, Citation, Summary, BodyHtml, FieldSchema, SignerRoles, RequiredAtIntake, SortOrder, IsActive) VALUES (N'OC-NPP-004', N'Notice of Privacy Practices Acknowledgment', N'06/2026', N'HIPAA 45 CFR 164.520 - 45 CFR Parts 160 and 164 - 42 CFR Part 2 - NC G.S. 122C-52 through 122C-56 - NC G.S. 130A-143', N'Confirms you received OneCare''s Notice of Privacy Practices, which explains your privacy rights and how your health information is used. You may decline to sign; we will document that.', N'<section class="cf-sec"><h3>Section 1 - Client Information</h3><div class="cf-client" data-slot="client"></div></section><section class="cf-sec"><h3>Section 2 - Your Privacy Rights</h3><p>OneCare Behavioral Health Services is committed to protecting your protected health information (PHI). Under HIPAA, you have the following rights:</p><table class="cf-tbl"><tr><th>Right to Access</th><td>You have the right to inspect and obtain a copy of your health records. Requests must be made in writing. A reasonable fee may be charged for copies.</td></tr><tr><th>Right to Amend</th><td>You may request that we correct or add information to your health record if you believe it is inaccurate or incomplete.</td></tr><tr><th>Right to Restrict</th><td>You may request restrictions on certain uses and disclosures of your PHI. We must agree if the disclosure is to a health plan for payment purposes and the services have been paid in full.</td></tr><tr><th>Right to Confidential Communications</th><td>You may request that we communicate with you at a specific address or phone number.</td></tr><tr><th>Right to Accounting</th><td>You have the right to receive a list of certain disclosures we have made of your PHI during the six (6) years prior to your request.</td></tr><tr><th>Right to a Copy of This Notice</th><td>You have the right to receive a paper copy of this notice at any time.</td></tr><tr><th>Right to File a Complaint</th><td>You may file a complaint with OneCare BHS or the U.S. Department of Health and Human Services if you believe your privacy rights have been violated. You will not be retaliated against.</td></tr></table></section><section class="cf-sec"><h3>Section 3 - How We Use and Disclose Your Information</h3><p>We may use and disclose your PHI without your authorization for the following purposes:</p><table class="cf-tbl"><tr><th>Treatment</th><td>Sharing information with your treatment team, referring providers, hospitals, and pharmacies to coordinate your care.</td></tr><tr><th>Payment</th><td>Submitting claims to Medicaid, your Prepaid Health Plan, or other insurance for payment of services.</td></tr><tr><th>Healthcare Operations</th><td>Quality improvement, staff training, compliance audits, accreditation reviews.</td></tr><tr><th>Required by Law</th><td>Reporting suspected abuse/neglect, responding to court orders, public health reporting.</td></tr><tr><th>Health and Safety</th><td>Preventing a serious and imminent threat to your health or safety, or the health or safety of others.</td></tr></table><p>Special protections apply to substance use disorder records (42 CFR Part 2), HIV/AIDS information (NC G.S. 130A-143), and psychotherapy notes. These require your specific written authorization before disclosure.</p></section><section class="cf-sec"><h3>Section 4 - AI Technology and Data Security</h3><p>OneCare BHS uses AI-assisted technology (GeniusOne AI) in its clinical operations. Your PHI processed by AI systems is subject to the same HIPAA protections as all other health information:</p><ol><li>All data is encrypted at rest (AES-256) and in transit (TLS 1.3)</li><li>AI systems do not make clinical decisions; all output is reviewed by qualified human staff</li><li>AI-processed data is not sold, shared with third parties, or used for marketing</li><li>You have the right to opt out of AI-assisted services at any time</li><li>Audit logs of all AI interactions involving your PHI are maintained for six (6) years</li></ol></section><section class="cf-sec"><h3>Section 5 - Contact Information</h3><table class="cf-tbl"><tr><th>Privacy Officer / Complaints</th><td>OneCare Behavioral Health Services - Email: privacy@onecarebhs.com - Phone: (to be completed by OneCare)</td></tr><tr><th>Federal Complaints</th><td>U.S. Dept. of Health and Human Services, Office for Civil Rights, 200 Independence Ave. SW, Washington, DC 20201 - 1-877-696-6775 - www.hhs.gov/ocr/privacy</td></tr></table></section><section class="cf-sec"><h3>Section 6 - Acknowledgment</h3><p>By signing below, I acknowledge that I have received a copy of the Notice of Privacy Practices of OneCare Behavioral Health Services. I have been given the opportunity to review the notice and ask questions.</p><p class="cf-fine">If the client refuses to sign - the date and time the notice was provided, the refusal, and the reason given (if any) are documented. A good-faith attempt to obtain acknowledgment is sufficient for HIPAA compliance.</p></section>', N'[]', N'Client', 1, 4, 1);
ELSE
  UPDATE dbo.ConsentTemplates SET Title = N'Notice of Privacy Practices Acknowledgment', Revision = N'06/2026', Citation = N'HIPAA 45 CFR 164.520 - 45 CFR Parts 160 and 164 - 42 CFR Part 2 - NC G.S. 122C-52 through 122C-56 - NC G.S. 130A-143', Summary = N'Confirms you received OneCare''s Notice of Privacy Practices, which explains your privacy rights and how your health information is used. You may decline to sign; we will document that.', BodyHtml = N'<section class="cf-sec"><h3>Section 1 - Client Information</h3><div class="cf-client" data-slot="client"></div></section><section class="cf-sec"><h3>Section 2 - Your Privacy Rights</h3><p>OneCare Behavioral Health Services is committed to protecting your protected health information (PHI). Under HIPAA, you have the following rights:</p><table class="cf-tbl"><tr><th>Right to Access</th><td>You have the right to inspect and obtain a copy of your health records. Requests must be made in writing. A reasonable fee may be charged for copies.</td></tr><tr><th>Right to Amend</th><td>You may request that we correct or add information to your health record if you believe it is inaccurate or incomplete.</td></tr><tr><th>Right to Restrict</th><td>You may request restrictions on certain uses and disclosures of your PHI. We must agree if the disclosure is to a health plan for payment purposes and the services have been paid in full.</td></tr><tr><th>Right to Confidential Communications</th><td>You may request that we communicate with you at a specific address or phone number.</td></tr><tr><th>Right to Accounting</th><td>You have the right to receive a list of certain disclosures we have made of your PHI during the six (6) years prior to your request.</td></tr><tr><th>Right to a Copy of This Notice</th><td>You have the right to receive a paper copy of this notice at any time.</td></tr><tr><th>Right to File a Complaint</th><td>You may file a complaint with OneCare BHS or the U.S. Department of Health and Human Services if you believe your privacy rights have been violated. You will not be retaliated against.</td></tr></table></section><section class="cf-sec"><h3>Section 3 - How We Use and Disclose Your Information</h3><p>We may use and disclose your PHI without your authorization for the following purposes:</p><table class="cf-tbl"><tr><th>Treatment</th><td>Sharing information with your treatment team, referring providers, hospitals, and pharmacies to coordinate your care.</td></tr><tr><th>Payment</th><td>Submitting claims to Medicaid, your Prepaid Health Plan, or other insurance for payment of services.</td></tr><tr><th>Healthcare Operations</th><td>Quality improvement, staff training, compliance audits, accreditation reviews.</td></tr><tr><th>Required by Law</th><td>Reporting suspected abuse/neglect, responding to court orders, public health reporting.</td></tr><tr><th>Health and Safety</th><td>Preventing a serious and imminent threat to your health or safety, or the health or safety of others.</td></tr></table><p>Special protections apply to substance use disorder records (42 CFR Part 2), HIV/AIDS information (NC G.S. 130A-143), and psychotherapy notes. These require your specific written authorization before disclosure.</p></section><section class="cf-sec"><h3>Section 4 - AI Technology and Data Security</h3><p>OneCare BHS uses AI-assisted technology (GeniusOne AI) in its clinical operations. Your PHI processed by AI systems is subject to the same HIPAA protections as all other health information:</p><ol><li>All data is encrypted at rest (AES-256) and in transit (TLS 1.3)</li><li>AI systems do not make clinical decisions; all output is reviewed by qualified human staff</li><li>AI-processed data is not sold, shared with third parties, or used for marketing</li><li>You have the right to opt out of AI-assisted services at any time</li><li>Audit logs of all AI interactions involving your PHI are maintained for six (6) years</li></ol></section><section class="cf-sec"><h3>Section 5 - Contact Information</h3><table class="cf-tbl"><tr><th>Privacy Officer / Complaints</th><td>OneCare Behavioral Health Services - Email: privacy@onecarebhs.com - Phone: (to be completed by OneCare)</td></tr><tr><th>Federal Complaints</th><td>U.S. Dept. of Health and Human Services, Office for Civil Rights, 200 Independence Ave. SW, Washington, DC 20201 - 1-877-696-6775 - www.hhs.gov/ocr/privacy</td></tr></table></section><section class="cf-sec"><h3>Section 6 - Acknowledgment</h3><p>By signing below, I acknowledge that I have received a copy of the Notice of Privacy Practices of OneCare Behavioral Health Services. I have been given the opportunity to review the notice and ask questions.</p><p class="cf-fine">If the client refuses to sign - the date and time the notice was provided, the refusal, and the reason given (if any) are documented. A good-faith attempt to obtain acknowledgment is sufficient for HIPAA compliance.</p></section>', FieldSchema = N'[]', SignerRoles = N'Client', RequiredAtIntake = 1, SortOrder = 4 WHERE Code = 'OC-NPP-004';
